'use strict';
(async function () {
  const data = await fetch('/content.json').then(r => { if (!r.ok) throw Error('Content unavailable'); return r.json(); });
  let lang = localStorage.getItem('niraby-language') || 'en', cleanups = [], currentProject = null;
  const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
  const t = x => typeof x === 'object' ? x?.[lang] || x?.en || '' : x || '';
  const tr = (en, ar) => lang === 'ar' ? ar : en;
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const galleryPositions = new Map();
  const projects = new Map(data.projects.map(p => [p.id,p]));
  const category = id => data.categories.find(c => c.id === id);
  const href = p => `/${p.category}/${p.id}/`;
  const num = n => String(n).padStart(2,'0');
  function pic(im, alt, eager=false, cls='') {
    if (!im) return `<div class="drawing-placeholder"><span>01 / 02 / 03</span><strong>${tr('Drawing archive','أرشيف الرسومات')}</strong></div>`;
    const widths = new Map([[Math.min(im.w,900),im.thumb],[Math.min(im.w,2200),im.display]]);
    return `<img class="${cls}" src="${im.display}" srcset="${[...widths].map(([w,url]) => `${url} ${w}w`).join(', ')}" sizes="(max-width:700px) 92vw, (max-width:1100px) 80vw, 65vw" width="${im.w}" height="${im.h}" alt="${esc(alt)}" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''}>`;
  }
  function header() { return `<a href="#main" class="skip-link">${tr('Skip to content','انتقل إلى المحتوى')}</a><header class="site-header"><a class="brand" href="/" aria-label="${esc(t(data.profile.name))}"><img class="brand-logo" src="${data.brand.logo}" alt="" width="46" height="61"><span class="brand-name">MUHAMMED<br>NIRABY</span></a><nav class="desktop-nav" aria-label="${tr('Main navigation','القائمة الرئيسية')}"><details class="work-menu"><summary>${tr('Work','الأعمال')} <span>⌄</span></summary><div>${data.categories.map(c=>`<a href="/${c.id}/">${t(c.short)}</a>`).join('')}</div></details><a href="/about/">${tr('About','عني')}</a><a href="/contact/">${tr('Contact','تواصل')}</a></nav><div class="header-right"><button class="language-button" id="language-switch" lang="${lang==='en'?'ar':'en'}">${tr('العربية','English')}</button><button class="menu-button" id="menu-open" aria-label="${tr('Open navigation','افتح القائمة')}" aria-haspopup="dialog"><span></span><span></span></button></div></header><dialog id="mobile-menu" class="mobile-menu"><div class="mobile-menu-top"><img src="${data.brand.logo}" alt="Muhammed Niraby" width="42" height="56"><button class="icon-button" data-close aria-label="${tr('Close navigation','أغلق القائمة')}">×</button></div><nav>${data.categories.map(c=>`<a href="/${c.id}/"><small>${c.code}</small>${t(c.short)} ↗</a>`).join('')}<a href="/about/">${tr('About','عني')}</a><a href="/contact/">${tr('Contact','تواصل')}</a></nav></dialog>`; }
  function footer() { return `<footer class="site-footer section-pad"><p class="eyebrow">${tr('HAVE A PROJECT IN MIND?','عندك مشروع جديد؟')}</p><a class="contact-title" href="/contact/">${tr("Let’s talk",'لنبدأ الحوار')}<span>↗</span></a><div class="footer-bottom"><a href="/" class="footer-brand"><img src="${data.brand.logo}" alt="" width="29" height="40">© 2026 ${t(data.profile.name)}</a><a href="mailto:${data.profile.email}">${data.profile.email}</a><a href="${data.profile.linkedin}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><button class="plain-button" id="back-top">${tr('Back to top ↑','إلى الأعلى ↑')}</button></div></footer>`; }
  function home() { return `<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="tiny-line"></span>${tr('ARCHITECTURE & INTERIORS','عمارة وتصميم داخلي')}</p><h1>${tr('Muhammed<br><span class="name-last">Niraby<span class="orange-dot">.</span></span>','محمد<br><span class="name-last">نيربي<span class="orange-dot">.</span></span>')}</h1><p class="hero-description">${tr('A considered approach to space,<br>material, and the way we experience them.','رؤية مدروسة للفراغ والخامة،<br>وللتجربة التي يصنعانها معاً.')}</p><a class="text-link" href="#disciplines">${tr('Explore the work','استكشف الأعمال')} <span aria-hidden="true">↗</span></a><div class="hero-location">${tr('DAMASCUS, SYRIA','دمشق، سورية')}<span>PORTFOLIO / 2026</span></div></div><figure class="hero-portrait"><img src="${data.brand.portrait}" alt="${esc(t(data.profile.name))}" width="1122" height="1402" fetchpriority="high"><figcaption>${tr('DESIGNER & VISUAL STORYTELLER','تصميم معماري وسرد بصري')}</figcaption></figure><span class="hero-index" aria-hidden="true">01—04</span></section><section class="disciplines section-pad" id="disciplines"><div class="section-heading"><p class="eyebrow">${tr('THE WORK','الأعمال')}</p><h2>${tr('Four disciplines.<br><em>One perspective.</em>','أربعة اختصاصات.<br><em>رؤية واحدة.</em>')}</h2><p>${tr('Explore each collection.','كل اختصاص في مجموعته الخاصة.')}</p></div><div class="discipline-grid">${data.categories.map((c,i)=>`<a class="discipline-card ${i%2?'offset-card':''} ${c.id==='technical'?'technical-card':''}" href="/${c.id}/"><div class="card-media">${pic(c.cover,t(c.title))}<span class="image-index">${c.code}</span></div><div class="card-caption"><div><h3>${t(c.title)}</h3><p>${num(c.count)} ${tr('PROJECTS','مشاريع')}</p></div><span class="circle-arrow" aria-hidden="true">↗</span></div></a>`).join('')}</div></section><section class="about-strip section-pad" id="about"><p class="eyebrow">${tr('BEHIND THE WORK','خلف الأعمال')}</p><h2>${tr('From the first idea<br>to the finest <em>detail.</em>','من الفكرة الأولى<br>إلى أدق <em>التفاصيل.</em>')}</h2><p>${t(data.profile.bio)}</p><a class="text-link" href="/about/">${tr('About Muhammed','تعرف على محمد')} <span>↗</span></a></section>`; }
  function card(p,i,feature=false) { return `<a class="project-card ${feature?'feature-project':''} ${p.category==='technical'?'technical-project':''} ${p.category==='films'&&p.cover?.h>p.cover?.w?'portrait-cover':''}" href="${href(p)}"><div class="project-card-media">${pic(p.cover,t(p.title),feature)}<span class="project-number">${num(i+1)}</span>${p.video?`<span class="film-label">▷ ${tr('FILM','فيلم')}</span>`:''}<span class="project-card-arrow" aria-hidden="true">↗</span></div><div class="project-card-caption"><div><p class="eyebrow">${t(p.type)}</p><h2>${t(p.title)}</h2></div><span>${p.year||p.code}</span></div></a>`; }
  function collection(c) { return `<section class="collection-intro section-pad"><a class="breadcrumb" href="/#disciplines">← ${tr('All disciplines','كل الاختصاصات')}</a><div class="collection-heading"><p class="eyebrow">${c.code} / ${tr('COLLECTION','مجموعة')}</p><h1>${t(c.title)}<span class="orange-dot">.</span></h1><p>${t(c.intro)}</p><span class="collection-count">${num(c.count)} <small>${tr('PROJECTS','مشاريع')}</small></span></div></section><section class="collection-grid section-pad" aria-label="${esc(t(c.title))}">${c.projects.map((id,i)=>card(projects.get(id),i,i===0)).join('')}</section><nav class="other-collections section-pad" aria-label="${tr('Other disciplines','اختصاصات أخرى')}"><p class="eyebrow">${tr('CONTINUE EXPLORING','تابع الاستكشاف')}</p>${data.categories.filter(x=>x.id!==c.id).map(x=>`<a href="/${x.id}/"><span>${x.code}</span>${t(x.short)} <b>↗</b></a>`).join('')}</nav>`; }
  function gallery(p,groups) {
    const technical=p.category==='technical';
    return `<section class="project-gallery section-pad ${technical?'technical-gallery':''}" id="project-gallery"><div class="gallery-heading"><div><p class="eyebrow">${tr('THE COLLECTION','مجموعة الصور')}</p><h2>${technical?tr('Drawings & details.','المخططات والتفاصيل.'):tr('A closer perspective.','منظور أقرب.')}</h2></div><button class="all-views-button" id="open-gallery-index"><span class="grid-icon" aria-hidden="true">▦</span>${tr('All views','كل اللقطات')} <span>${num(p.images.length)}</span></button></div>${groups.length>1?`<div class="gallery-tabs" role="group" aria-label="${tr('Gallery filter','تصفية المعرض')}"><button class="active" data-group="all" aria-pressed="true">${tr('All','الكل')}</button>${groups.map(([g,label])=>`<button data-group="${g}" aria-pressed="false">${label} <span>${p.images.filter(im=>im.group===g).length}</span></button>`).join('')}</div>`:''}<div class="gallery-presentation"><div class="gallery-main-stage" tabindex="0" role="group" aria-label="${tr('Project image gallery','معرض صور المشروع')}"><button id="gallery-expand" class="gallery-photo-button" aria-label="${tr('Open full screen image','افتح الصورة بكامل الشاشة')}"><img id="gallery-main-image" src="${p.images[0]?.display||''}" alt="${esc(t(p.images[0]?.label)||t(p.title))}" loading="lazy"><span class="gallery-expand-label">⤢ <span>${tr('Full screen','كامل الشاشة')}</span></span></button><button class="gallery-step gallery-back" aria-label="${tr('Previous image','الصورة السابقة')}">←</button><button class="gallery-step gallery-forward" aria-label="${tr('Next image','الصورة التالية')}">→</button></div><div class="gallery-main-caption" aria-live="polite"><div class="gallery-position"><strong id="gallery-current">01</strong><span>/ <span id="gallery-total">${num(p.images.length)}</span></span></div><div class="gallery-caption-copy"><p id="gallery-view-title">${t(p.images[0]?.label)||t(p.title)}</p><p id="gallery-view-description"></p></div><span class="gallery-key-hint" aria-hidden="true">← &nbsp; →</span></div><div class="gallery-thumbnails" aria-label="${tr('Choose an image','اختر صورة')}">${p.images.map((im,i)=>`<button class="gallery-thumbnail ${i===0?'active':''}" data-thumb="${i}" data-image-group="${im.group}" aria-label="${esc((t(im.label)||t(p.title))+' — '+(i+1))}" aria-current="${i===0?'true':'false'}"><img src="${im.thumb}" alt="" width="140" height="100" loading="lazy"><span>${num(i+1)}</span></button>`).join('')}</div></div><dialog class="gallery-index" id="gallery-index"><div class="gallery-index-header"><div><p class="eyebrow">${t(p.title)}</p><h2>${tr('The complete collection','المجموعة كاملة')} <span>${num(p.images.length)}</span></h2></div><button class="icon-button" data-close aria-label="${tr('Close all views','إغلاق كل اللقطات')}">×</button></div><div class="gallery-index-grid">${p.images.map((im,i)=>`<button data-index-image="${i}" data-image-group="${im.group}"><img src="${im.thumb}" alt="${esc(t(im.label)||t(p.title)+' — '+num(i+1))}" loading="lazy" width="300" height="220"><span><b>${num(i+1)}</b>${t(im.label)||''}</span></button>`).join('')}</div></dialog></section>`;
  }

  function project(p) {
    const c=category(p.category), order=c.projects, next=projects.get(order[(order.indexOf(p.id)+1)%order.length]);
    const title=`<div class="project-hero-title"><a class="breadcrumb" href="/${c.id}/">← ${t(c.short)}</a><p class="eyebrow">${p.code} / ${t(p.type)}</p><h1>${t(p.title)}</h1></div>`;
    const hero=p.video?`<section class="film-scene ${p.video.h>p.video.w?'portrait-project-film':p.video.w/p.video.h>2?'wide-project-film':''}" aria-label="${tr('Scroll controlled project film','فيلم المشروع يتحرك مع التمرير')}"><div class="film-sticky"><img class="film-poster" src="${p.video.poster}" alt="${esc(t(p.title))}" fetchpriority="high"><video id="project-film" muted playsinline preload="none" poster="${p.video.poster}" data-src="${p.video.src}" aria-label="${esc(t(p.title))}"></video><div class="film-shade"></div>${title}<div class="film-controls"><p class="scroll-caption">↓ ${tr('SCROLL TO EXPLORE','مرّر لاستكشاف المشروع')}</p><button class="film-play" data-play-film>▷ ${tr('Play selected film','شاهد المقطع المختار')}</button><a href="#project-details">${tr('Project details','تفاصيل المشروع')} ↓</a></div><div class="film-progress" aria-hidden="true"><span></span></div></div></section>`:`<section class="image-project-hero ${p.category==='technical'?'drawing-hero':''}">${pic(p.cover,t(p.title),true)}<div class="film-shade"></div>${title}<a class="image-hero-scroll" href="#project-details">${tr('Explore project','استكشف المشروع')} ↓</a></section>`;
    const groups=[['gallery',tr('Images','الصور')],['study',p.category==='films'?tr('Scene studies','دراسات المشهد'):tr('Model studies','دراسات النموذج')],['drawings',tr('Drawings & boards','الرسومات واللوحات')]].filter(([g])=>p.images.some(im=>im.group===g));
    return hero+`<section class="project-overview section-pad" id="project-details"><div><p class="eyebrow">${tr('PROJECT NOTES','عن المشروع')}</p><h2>${t(p.headline)}</h2></div><div class="project-story"><p>${t(p.description)}</p>${p.category==='technical'?`<p class="drawing-note">${tr('Selected drawing previews. Some original annotations are omitted in the web export.','معاينات مختارة من الرسومات. بعض الملاحظات الأصلية غير ظاهرة في نسخة العرض على الويب.')}</p>`:''}<dl class="project-facts">${[[tr('Discipline','الاختصاص'),t(c.short)],[tr('Location','الموقع'),t(p.location)],[tr('Year','السنة'),p.year],[tr('My role','دوري'),t(p.role)],[tr('Context / credits','السياق والمساهمات'),t(p.credit)]].filter(x=>x[1]).map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${p.video?`<button class="text-link" data-play-film>▷ ${tr('Watch the selected excerpt','شاهد المقطع المختار')} <small>${Math.round(p.video.duration)} ${tr('sec','ثانية')}</small></button>`:''}${p.documents.map(d=>`<a class="document-link" href="${d.url}" target="_blank" rel="noopener">↗ ${t(d.title)} · PDF${d.pages?` / ${d.pages} ${tr('pages','صفحة')}`:''}</a>`).join('')}</div></section>${gallery(p,groups)}<nav class="project-next section-pad" aria-label="${tr('Project navigation','التنقل بين المشاريع')}"><a class="breadcrumb" href="/${c.id}/">← ${tr('Back to','العودة إلى')} ${t(c.short)}</a>${next.id!==p.id?`<a class="next-project-link" href="${href(next)}"><span class="eyebrow">${tr('NEXT PROJECT','المشروع التالي')}</span><strong>${t(next.title)}</strong><span aria-hidden="true">↗</span></a>`:''}</nav><dialog id="image-viewer" class="image-viewer"><div class="viewer-toolbar"><span id="viewer-count"></span><span class="viewer-tools"><button id="zoom-out" aria-label="${tr('Zoom out','تصغير')}">−</button><button id="zoom-reset">100%</button><button id="zoom-in" aria-label="${tr('Zoom in','تكبير')}">+</button><a id="original-image" target="_blank" rel="noopener">${tr('Original size ↗','الحجم الأصلي ↗')}</a><button data-close aria-label="${tr('Close image','أغلق الصورة')}">×</button></span></div><div class="viewer-stage"><img id="viewer-image" alt=""><button class="viewer-prev" aria-label="${tr('Previous image','الصورة السابقة')}">‹</button><button class="viewer-next" aria-label="${tr('Next image','الصورة التالية')}">›</button></div><p class="viewer-note">${tr('Use + to zoom, drag to explore. Arrow keys to navigate.','كبّر بزر + واسحب لاستكشاف الصورة. تنقّل بمفاتيح الأسهم.')}</p></dialog><dialog id="film-viewer" class="film-viewer"><button data-close class="film-close" aria-label="${tr('Close film','أغلق الفيلم')}">×</button><video controls playsinline preload="none" poster="${p.video?.poster||''}"></video><p>${t(p.title)} · ${tr('Selected excerpt','مقطع مختار')}</p></dialog>`;
  }
  function about(cv=false) { const p=data.profile; return `<section class="about-page section-pad ${cv?'cv-page':''}"><div class="about-intro"><div><p class="eyebrow">${tr('DESIGNER / VISUAL STORYTELLER','مصمم معماري / سرد بصري')}</p><h1>${t(p.name)}<span class="orange-dot">.</span></h1><p class="about-lead">${t(p.bio)}</p>${cv?`<button class="text-link" id="print-cv">${tr('Print / save PDF','طباعة / حفظ PDF')} ↗</button>`:`<a class="text-link" href="/cv/">${tr('View résumé','عرض السيرة الذاتية')} ↗</a>`}<div class="about-contact"><a href="mailto:${p.email}">${p.email}</a><a href="tel:${p.phone}" dir="ltr">${p.phone}</a></div></div><figure><img src="${data.brand.portrait}" alt="${esc(t(p.name))}" width="1122" height="1402"></figure></div><div class="experience-section"><h2>${tr('Experience','الخبرة')}</h2><div>${p.experience.map(e=>`<article class="experience-row"><span>${e.period}</span><div><h3>${t(e.role)}</h3><h4>${e.company}</h4><p>${t(e.description)}</p></div></article>`).join('')}</div></div><div class="education-section"><h2>${tr('Education','الدراسة')}</h2><p>${t(p.education)}</p></div><div class="tools-section"><h2>${tr('Tools of the practice','أدوات العمل')}</h2><div>${p.tools.map(tool=>`<span>${tool}</span>`).join('')}</div></div></section>`; }
  function contact() {return `<section class="contact-page section-pad"><p class="eyebrow">${tr('START A CONVERSATION','لنبدأ حواراً')}</p><h1>${tr('Good spaces start<br>with a conversation','الفراغات الجيدة تبدأ<br>بحوار')}<span class="orange-dot">.</span></h1><div class="contact-grid"><p>${tr('For architectural and interior design, visualization, or a film that tells the story of your project.','للتصميم المعماري والداخلي، أو الإظهار، أو فيلم يروي حكاية مشروعك.')}</p><div><a href="mailto:${data.profile.email}"><small>${tr('EMAIL','البريد الإلكتروني')}</small><span>${data.profile.email}</span><b>↗</b></a><a href="tel:${data.profile.phone}"><small>${tr('PHONE','الهاتف')}</small><span dir="ltr">${data.profile.phone}</span><b>↗</b></a><a href="${data.profile.linkedin}" target="_blank" rel="noopener noreferrer"><small>${tr('CONNECT','تواصل')}</small><span>LinkedIn</span><b>↗</b></a></div></div><p class="contact-location">${tr('Based in Damascus, Syria.','دمشق، سورية.')}</p></section>`;}
  const motion=matchMedia('(prefers-reduced-motion: reduce)');
  function bind() {
    $('#language-switch').onclick=()=>{const y=scrollY;lang=lang==='en'?'ar':'en';localStorage.setItem('niraby-language',lang);render(false);scrollTo(0,y);};
    $('#menu-open').onclick=()=>$('#mobile-menu').showModal();
    $$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
    $$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
    $('#back-top').onclick=()=>scrollTo({top:0,behavior:motion.matches?'instant':'smooth'});
    $('#print-cv')?.addEventListener('click',()=>print());
    if(currentProject)bindProject(currentProject);
  }
  function bindProject(p) {
    const viewer=$('#image-viewer'),vi=$('#viewer-image'),stageImage=$('#gallery-main-image'),sheet=$('#gallery-index'),direction=lang==='ar'?-1:1;
    $('.gallery-back').textContent=tr('←','→');$('.gallery-forward').textContent=tr('→','←');
    $('.viewer-prev').textContent=tr('‹','›');$('.viewer-next').textContent=tr('›','‹');
    let index=0,selected=0,scale=1,x=0,y=0,drag=null,available=p.images.map((_,i)=>i);
    function setFrame(i,bringIntoView=false){
      selected=i;const im=p.images[i];if(!im)return;galleryPositions.set(p.id,i);
      stageImage.src=im.display;stageImage.alt=t(im.label)||t(p.title)+' — '+num(i+1);
      $('.gallery-main-stage').classList.toggle('is-drawing',im.group==='drawings');
      $('#gallery-current').textContent=num(available.indexOf(i)+1);$('#gallery-total').textContent=num(available.length);
      $('#gallery-view-title').textContent=t(im.label)||t(p.title);$('#gallery-view-description').textContent=t(im.description);
      $$('[data-thumb]').forEach(b=>{const active=+b.dataset.thumb===i;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'true':'false');});
      if(bringIntoView){const thumb=$(`[data-thumb="${i}"]`),rail=$('.gallery-thumbnails');const r=thumb.getBoundingClientRect(),rr=rail.getBoundingClientRect();if(r.left<rr.left||r.right>rr.right)rail.scrollBy({left:(r.left+r.width/2)-(rr.left+rr.width/2),behavior:motion.matches?'instant':'smooth'});}
      const next=p.images[available[(available.indexOf(i)+1)%available.length]];if(next&&next!==im){const preload=new Image();preload.src=next.display;}
    }
    function step(delta){const position=available.indexOf(selected);setFrame(available[(position+delta+available.length)%available.length],true);}
    $('.gallery-back').onclick=()=>step(-1);$('.gallery-forward').onclick=()=>step(1);
    $('.gallery-main-stage').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();step(direction);}if(e.key==='ArrowLeft'){e.preventDefault();step(-direction);}});
    $$('[data-thumb]').forEach(b=>b.onclick=()=>setFrame(+b.dataset.thumb,true));
    $('#open-gallery-index').onclick=()=>{$('[data-group=all]')?.click();sheet.showModal();};
    $$('[data-index-image]').forEach(b=>b.onclick=()=>{setFrame(+b.dataset.indexImage,true);sheet.close();$('.gallery-main-stage').focus({preventScroll:true});});
    $$('[data-group]').forEach(b=>b.onclick=()=>{const g=b.dataset.group;available=p.images.map((im,i)=>({im,i})).filter(({im})=>g==='all'||im.group===g).map(({i})=>i);$$('[data-group]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});$$('[data-image-group]').forEach(el=>el.hidden=g!=='all'&&el.dataset.imageGroup!==g);setFrame(available.includes(selected)?selected:available[0],true);});
    function transform(){vi.style.transform=`translate(${x}px,${y}px) scale(${scale})`;$('#zoom-reset').textContent=Math.round(scale*100)+'%';vi.classList.toggle('zoomed',scale>1);}
    function zoom(value){scale=Math.max(1,Math.min(8,value));if(scale===1)x=y=0;transform();}
    function show(i){index=i;const im=p.images[index];scale=1;x=0;y=0;transform();vi.src=im.full;vi.alt=t(im.label)||t(p.title)+' — '+num(index+1);$('#viewer-count').textContent=num(available.indexOf(index)+1)+' / '+num(available.length);$('#original-image').href=im.full;}
    function viewerStep(delta){show(available[(available.indexOf(index)+delta+available.length)%available.length]);}
    let suppressOpenUntil=0,touchStart=null;
    $('#gallery-expand').onclick=()=>{if(performance.now()<suppressOpenUntil)return;show(selected);viewer.showModal();};
    $('#gallery-expand').addEventListener('touchstart',e=>{if(e.touches.length===1)touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});
    $('#gallery-expand').addEventListener('touchend',e=>{if(!touchStart||!e.changedTouches.length)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5){suppressOpenUntil=performance.now()+450;step((dx<0?1:-1)*direction);}},{passive:true});
    $('#zoom-in').onclick=()=>zoom(scale+.5);$('#zoom-out').onclick=()=>zoom(scale-.5);$('#zoom-reset').onclick=()=>zoom(1);
    $('.viewer-prev').onclick=()=>viewerStep(-1);$('.viewer-next').onclick=()=>viewerStep(1);
    viewer.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();viewerStep(direction);}if(e.key==='ArrowLeft'){e.preventDefault();viewerStep(-direction);}});
    viewer.addEventListener('close',()=>setFrame(index,true));
    vi.addEventListener('dblclick',()=>zoom(scale>1?1:2));
    const pointers=new Map();let pinch=null;
    const distance=()=>{const a=[...pointers.values()];return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);};
    vi.addEventListener('pointerdown',e=>{e.preventDefault();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});vi.setPointerCapture(e.pointerId);if(pointers.size===2){pinch={distance:distance(),scale};drag=null;}else drag={px:e.clientX,py:e.clientY,x,y};});
    vi.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch)zoom(pinch.scale*distance()/pinch.distance);else if(drag&&scale>1){x=drag.x+e.clientX-drag.px;y=drag.y+e.clientY-drag.py;transform();}});
    const release=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;if(pointers.size===1){const point=[...pointers.values()][0];drag={px:point.x,py:point.y,x,y};}};vi.addEventListener('pointerup',release);vi.addEventListener('pointercancel',release);
    $('.viewer-stage').addEventListener('wheel',e=>{if(e.ctrlKey)return;e.preventDefault();zoom(scale+(e.deltaY<0?.25:-.25));},{passive:false});
    setFrame(Math.min(galleryPositions.get(p.id)||0,p.images.length-1));
    if(!p.video)return;
    const fv=$('#film-viewer'),player=$('#film-viewer video');
    $$('[data-play-film]').forEach(b=>b.onclick=()=>{if(!player.src)player.src=p.video.src;fv.showModal();player.play().catch(()=>{});});fv.addEventListener('close',()=>player.pause());
    const scene=$('.film-scene'), video=$('#project-film');let raf=0,target=0,ready=false;
    function seek(){if(ready&&!video.seeking&&Math.abs(video.currentTime-target)>.022)try{video.currentTime=target;}catch{}}
    function update(){raf=0;const r=scene.getBoundingClientRect(),travel=scene.offsetHeight-innerHeight;const progress=Math.max(0,Math.min(1,-r.top/Math.max(1,travel)));target=progress*Math.max(0,(video.duration||p.video.duration)-.045);scene.style.setProperty('--film-progress',progress);seek();}
    function onscroll(){if(!raf)raf=requestAnimationFrame(update);}
    function configure(){scene.classList.toggle('reduced-film',motion.matches);if(!motion.matches){scene.style.setProperty('--film-travel',Math.min(3400,Math.max(1500,p.video.duration*105))+'px');onscroll();}}
    video.addEventListener('loadedmetadata',()=>{ready=true;update();});video.addEventListener('seeked',seek);
    video.addEventListener('loadeddata',()=>video.classList.add('ready'));
    const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&!video.src&&!motion.matches){video.src=video.dataset.src;video.load();}},{rootMargin:'300px'});observer.observe(scene);
    window.addEventListener('scroll',onscroll,{passive:true});window.addEventListener('resize',onscroll);motion.addEventListener('change',configure);configure();
    cleanups.push(()=>{cancelAnimationFrame(raf);observer.disconnect();window.removeEventListener('scroll',onscroll);window.removeEventListener('resize',onscroll);motion.removeEventListener('change',configure);video.pause();player.pause();});
  }
  function render(reset=true) {
    cleanups.forEach(f=>f());cleanups=[];currentProject=null;
    const parts=location.pathname.split('/').filter(Boolean);let content,title;
    if(!parts.length){content=home();title=tr('Architecture & Interiors','العمارة والتصميم الداخلي');}
    else if(category(parts[0])&&parts.length===1){const c=category(parts[0]);content=collection(c);title=t(c.title);}
    else if(parts.length===2&&projects.has(parts[1])&&projects.get(parts[1]).category===parts[0]){currentProject=projects.get(parts[1]);content=project(currentProject);title=t(currentProject.title);}
    else if(parts[0]==='about'||parts[0]==='cv'){content=about(parts[0]==='cv');title=tr(parts[0]==='cv'?'Résumé':'About',parts[0]==='cv'?'السيرة الذاتية':'عني');}
    else if(parts[0]==='contact'){content=contact();title=tr('Contact','تواصل');}
    else {content=`<section class="section-pad not-found"><h1>404</h1><p>${tr('This page could not be found.','هذه الصفحة غير موجودة.')}</p><a class="text-link" href="/">${tr('Return home','العودة للرئيسية')} ↗</a></section>`;title='404';}
    document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
    document.title=title+' — '+t(data.profile.name);document.querySelector('meta[name="description"]').content=currentProject?t(currentProject.description):t(data.profile.bio);
    document.body.innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();
    bind();if(reset)scrollTo(0,0);
    if(location.hash)requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView());
  }
  document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target||a.download||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;const url=new URL(a.href,location.href);if(url.origin!==location.origin||/\.(pdf|webp|png|jpg|svg|mp4)$/i.test(url.pathname))return;if(url.pathname===location.pathname&&url.hash){$('#mobile-menu')?.close();return;}e.preventDefault();history.replaceState({y:scrollY},'',location.href);history.pushState({},'',url.pathname+url.search+url.hash);render();$('#main')?.focus({preventScroll:true});});
  history.scrollRestoration='manual';window.addEventListener('popstate',e=>{render(false);requestAnimationFrame(()=>scrollTo(0,e.state?.y||0));});
  render(false);
})().catch(error=>{console.error(error);document.body.innerHTML='<main class="section-pad"><h1>Muhammed Niraby</h1><p>Please reload the page. / يرجى إعادة تحميل الصفحة.</p><a href="mailto:nairabymhmd@gmail.com">nairabymhmd@gmail.com</a></main>';});
